INSERT INTO `buff` VALUES (14101,'1.4','1','诛心','代理人的属性异常积蓄效率提升30%，[紊乱]效果造成的伤害提升40%。\n对敌人施加[紊乱]效果时，全队回复10点能量，代理人的攻击力提升25%，持续30秒，能量回复效果20秒内最多触发一次。','/buff_image/1411.webp',NULL),(14102,'1.4','1','速决','代理人的攻击力提升20%，喧响值获得效率提升20%；发动[终结技]时，代理人的攻击力额外提升15%，持续15秒。\n[终结技]造成的伤害提升40%，造成的失衡值提升20%，累积的属性异常积蓄值提升20%。','/buff_image/1412.webp',NULL),(14103,'1.4','1','破招','[普通攻击]、[闪避反击]、[强化特殊技]、[冲刺攻击]造成的伤害提升30%。\n触发[极限闪避]或[极限支援]后，全队攻击力提升10%，暴击伤害提升10%，持续15秒，最多叠加3层，每层效果单独结算持续时间。','/buff_image/1413.webp',NULL),(14201,'1.4','2','游刃','代理人的属性异常积蓄效率提升25%，异常精通提升40点。\n对敌人施加属性异常效果时，代理人额外获得500点喧响值，攻击力提升30%，持续15秒，喧响值获得效果15秒内最多触发一次。','/buff_image/1421.webp',NULL),(14202,'1.4','2','速决','代理人的攻击力提升20%，喧响值获取效率提升20%；发动[终结技]时，代理人的攻击力额外提升15%，持续15秒。\n[终结技]造成的伤害提升40%，造成的失衡值提升20%，累积的属性异常积蓄值提升20%。','/buff_image/1422.webp',NULL),(14203,'1.4','2','倾覆','代理人造成的失衡值提升25%，[连携技]造成的伤害提升80%。\n发动[连携技]时，代理人回复20点能量，造成的伤害提升50%，持续20秒。','/buff_image/1423.webp',NULL),(15101,'1.5','1','异象','代理人的属性异常积蓄效率提升20%。\n对敌人施加属性异常效果时，全队提升60点异常精通，紊乱造成的伤害提升40%，持续15秒。','/buff_image/1511.webp',NULL),(15102,'1.5','1','霜雷','代理人的电属性伤害和冰属性伤害将提升25%。\n[普通攻击]、[闪避反击]和[冲刺攻击]造成的伤害提升40%，无视敌人15%防御力。','/buff_image/1512.webp',NULL),(15103,'1.5','1','驰援','代理人的能量获取效率提升25%，[快速支援]造成的伤害提升50%。\n每次使用[快速支援]时，全队的攻击力提升10%，持续20秒，最多可叠加3层，重复触发时刷新持续时间。','/buff_image/1513.webp',NULL),(15201,'1.5','2','破招','[普通攻击]、[闪避反击]、[强化特殊技]、[冲刺攻击]造成的伤害提升30%。\n触发[极限闪避]或[极限支援]后，全队攻击力提升10%，暴击伤害提升10%，持续15秒，最多叠加3层，每层效果单独结算持续时间。','/buff_image/1521.webp',NULL),(15202,'1.5','2','驰援','代理人的能量获取效率提升25%，[快速支援]造成的伤害提升50%。\n每次使用[快速支援]时，全队的攻击力提升10%，持续20秒，最多可叠加3层，重复触发时刷新持续时间。','/buff_image/1522.webp',NULL),(15203,'1.5','2','破衡','代理人造成的失衡值提升15%，[连携技]造成的伤害提升60%。\n每次使用[连携技]时，全队的攻击力提升10%，持续20秒，最多可叠加4层，每层效果单独结算持续时间。','/buff_image/1523.webp',NULL),(15301,'1.5','3','破衡','代理人造成的失衡值提升15%，[连携技]造成的伤害提升60%。\n每次使用[连携技]时，全队的攻击力提升10%，持续20秒，最多可叠加4层，每层效果单独结算持续时间。','/buff_image/1531.webp',NULL),(15302,'1.5','3','灼冽','代理人的火属性异常积蓄效率和冰属性异常积蓄效率将提升20%，攻击力提升25%。\n对敌人施加属性异常效果时，代理人回复300点喧响值，提升80点异常精通，持续15秒。','/buff_image/1